def sha_bytes(raw):
    return hashlib.sha256(raw).hexdigest()


def read_complete(path, record):
    raw=path.read_bytes()
    if (len(raw)!=record['bytes'] or len(raw)>=100000
            or sha_bytes(raw)!=record['sha256']):
        raise ValueError('Use the complete exact source: '+str(path))
    return raw


def functions(tree):
    result={}
    for node in tree.body:
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)):
            key=node.name
            if key in result:raise ValueError('Duplicate complete function: '+key)
            result[key]=node
        elif isinstance(node,ast.ClassDef):
            for item in node.body:
                if isinstance(item,(ast.FunctionDef,ast.AsyncFunctionDef)):
                    key=node.name+'.'+item.name
                    if key in result:raise ValueError('Duplicate complete method: '+key)
                    result[key]=item
    return result


def check_source(raw, name):
    tree=ast.parse(raw,filename=name)
    compile(tree,name,'exec')
    for node in ast.walk(tree):
        if isinstance(node,ast.Dict):
            seen=set()
            for key in node.keys:
                try:value=ast.literal_eval(key)
                except (ValueError,TypeError,SyntaxError):continue
                try:hash(value)
                except TypeError:continue
                if value in seen:raise ValueError('Duplicate literal dictionary key in '+name)
                seen.add(value)
    return tree


def method_delta(role, old, new):
    before=functions(old);after=functions(new)
    allowed=set(PLAN['allowed_function_changes'][role])
    added=set(PLAN['new_complete_functions'][role])
    if set(after)!=set(before)|added:
        raise ValueError('A complete original function disappeared or an undeclared one was added: '+role)
    unchanged=[]
    for name,node in before.items():
        if name not in allowed:
            if ast.dump(node,include_attributes=False)!=ast.dump(after[name],include_attributes=False):
                raise ValueError('Changed retained complete body: '+role+': '+name)
            unchanged.append(name)
    if role=='endpoint':
        original=copy.deepcopy(after['ZeroClosureOperator._closure_jets_original'])
        original.name='_closure_jets'
        if (ast.dump(original,include_attributes=False)
                !=ast.dump(before['ZeroClosureOperator._closure_jets'],include_attributes=False)):
            raise ValueError('The entire original closure formula must only be renamed')
    return dict(all_original_functions_retained=True,
        unchanged_complete_functions=unchanged,
        explicitly_changed_functions=sorted(allowed),
        new_complete_functions=sorted(added))


def reproduce(args):
    source=args.source_directory.resolve()
    output=args.output_directory.resolve()
    records={}
    inputs={}
    helper=PLAN['new_helper']
    helper_path=source/helper['name']
    helper_raw=read_complete(helper_path,helper)
    check_source(helper_raw,helper['name'])
    inputs[helper_path]=helper_raw
    generated={helper['name']:helper_raw}
    records[helper['name']]=dict(bytes=len(helper_raw),sha256=sha_bytes(helper_raw),
        complete_new_helper=True)
    for role,item in PLAN['derived_sources'].items():
        parent_path=source/item['parent']['name']
        parent=read_complete(parent_path,item['parent'])
        inputs[parent_path]=parent
        text=parent.decode('utf-8')
        for change in item['patches']:
            if change['op']!='replace' or text.count(change['old'])!=change['count']:
                raise ValueError('Full-source replacement does not match: '+role)
            text=text.replace(change['old'],change['new'])
        raw=text.encode('utf-8')
        if (len(raw)!=item['bytes'] or sha_bytes(raw)!=item['sha256']
                or len(raw)>=100000):
            raise ValueError('The complete generated body differs: '+role)
        restored=text
        for change in reversed(item['patches']):
            if restored.count(change['new'])!=change['count']:
                raise ValueError('Exact reverse replacement does not match: '+role)
            restored=restored.replace(change['new'],change['old'])
        if restored.encode('utf-8')!=parent:
            raise ValueError('Every complete parent byte must be recoverable: '+role)
        old_tree=check_source(parent,item['parent']['name'])
        new_tree=check_source(raw,item['name'])
        delta=method_delta(role,old_tree,new_tree)
        records[item['name']]=dict(role=role,bytes=len(raw),sha256=sha_bytes(raw),
            parent_complete_sha256=item['parent']['sha256'],
            exact_complete_parent_bytes_restored=True,method_delta=delta)
        generated[item['name']]=raw
    for path,raw in inputs.items():
        if path.read_bytes()!=raw:raise ValueError('An entire input source changed during reproduction')
    if args.verify_existing:
        for name,raw in generated.items():
            if (output/name).read_bytes()!=raw:
                raise ValueError('The existing entire output differs: '+name)
    else:
        output.mkdir(parents=True,exist_ok=True)
        for name,raw in generated.items():
            path=(output/name).resolve()
            if path in inputs and path.read_bytes()!=raw:
                raise ValueError('Do not overwrite an original full source')
            if path.exists() and path.read_bytes()!=raw:
                raise ValueError('Use a new output directory; keep prior complete versions')
            path.write_bytes(raw)
    return dict(schema=PLAN['schema'],complete_source_reproduction=True,
        all_nine_whole_sources=True,verify_existing=bool(args.verify_existing),
        source_AST_and_compile_only=True,numerical_execution_performed=False,
        exact_original_sources_retained=True,records=records)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source-directory',type=Path,required=True)
    parser.add_argument('--output-directory',type=Path,required=True)
    parser.add_argument('--verify-existing',action='store_true')
    args=parser.parse_args()
    print(json.dumps(reproduce(args),sort_keys=True,indent=2,allow_nan=False))


if __name__=='__main__':
    main()
